export const toSlug = (value) => value.toLowerCase().replace(/&/g, 'and').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
export const serviceRecords = practiceAreas.flatMap(area => area.services.map(title => ({
  slug: toSlug(title), title, area: area.title, areaSlug: area.slug,
  description: `${title} matters require a fact-specific approach, sound procedure and careful documentation.`
})));

